func currentBranch(ctx context.Context) string {
	repoRoot, err := paths.WorktreeRoot(ctx)
	if err != nil {
		return ""
	}
	name := gitString(ctx, repoRoot, "rev-parse", "--abbrev-ref", "HEAD")
	if name == detachedHEADDisplay {
		return ""
	}
	return name
