63	func TestReviewMarker_RoundTrip(t *testing.T) {
64		tmp := setupReviewTestRepoWithCommit(t)
65	
66		m := PendingReviewMarker{
67			AgentName:   "claude-code",
68			Skills:      []string{testReviewSkill},
69			Prompt:      "Please run these review skills in order:\n  1. " + testReviewSkill + "\n",
70			StartingSHA: "deadbeef",
71			StartedAt:   time.Now().UTC(),
72		}
73		ctx := context.Background()
74		if err := WritePendingReviewMarker(ctx, m); err != nil {
75			t.Fatalf("write: %v", err)
76		}
77		got, ok, err := ReadPendingReviewMarker(ctx)
78		if err != nil {
79			t.Fatalf("read: %v", err)
80		}
81		if !ok {
82			t.Fatal("expected marker present")
83		}
84		if got.AgentName != m.AgentName || got.StartingSHA != m.StartingSHA {
85			t.Errorf("roundtrip mismatch: %+v", got)
86		}
87		if got.Prompt != m.Prompt {
88			t.Errorf("Prompt roundtrip mismatch: got %q want %q", got.Prompt, m.Prompt)
89		}
90	
91		// Marker file must live under .git/entire-sessions/, not the worktree.
92		// Check before clearing so the file is actually present on disk.
93		markerGlob := filepath.Join(tmp, ".git", "entire-sessions", "*")
94		entries, err := filepath.Glob(markerGlob)
95		if err != nil {
