98		if len(entries) == 0 {
99			t.Errorf("no marker file found under %s — path resolution may have regressed", markerGlob)
100		}
101	
102		if err := ClearPendingReviewMarker(ctx); err != nil {
103			t.Fatalf("clear: %v", err)
104		}
105		_, ok, err = ReadPendingReviewMarker(ctx)
106		if err != nil {
107			t.Fatalf("read-after-clear: %v", err)
108		}
109		if ok {
110			t.Error("expected marker absent after clear")
111		}
112	}
